            "text": "{\"findings\":[{\"tipo\":\"GC\",\"causa_raiz\":\"Alocação excessiva e contínua de memória heap no método Update provocada por concatenação de strings em laço for (s += i.ToString()) e criação repetida de arrays de objetos, acumulando mais de 2.6 MB de lixo por frame e disparando coletas síncronas do Garbage Collector que paralisam a CPU por até 17.94 ms.\",\"codigo_refatorado\":\"using System; using UnityEngine; namespace PerformanceAdvisor.StressTest { public class StressTestScene : MonoBehaviour { public bool stressGc = false; public bool stressCpu = false; public bool stressDraw = false; public GameObject testPrefab; [Range(1, 20)] public float spawnRadius = 10f; [Range(1, 50)] public int cubesPerFrame = 1; public bool useUniqueMaterials = false; [Range(1, 512)] public int cpuScansPerFrame = 1; public int emptyObjects = 0; public int gcConcatIterations = 1000; public int gcArrayAllocs = 0; public int overdrawLayers = 0; public Material overdrawMaterial; [Range(0, 2000)] public int prepopulateCount = 0; private MaterialPropertyBlock _propBlock; private static readonly int ColorProp = Shader.PropertyToID(\\\"_Color\\\"); private void Awake() { _propBlock = new MaterialPropertyBlock(); } private void Start() { if (prepopulateCount \u003e 0 && testPrefab != null) { for (int i = 0; i \u003c prepopulateCount; i++) { SpawnOne(); } } for (int i = 0; i \u003c emptyObjects; i++) { new GameObject(\\\"Empty_\\\" + i); } if (overdrawLayers \u003e 0 && overdrawMaterial != null) { BuildOverdrawLayers(); } } private void BuildOverdrawLayers() { Camera cam = Camera.main; if (cam == null) return; float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad; for (int i = 0; i \u003c overdrawLayers; i++) { float d = cam.nearClipPlane + 0.05f + i * 0.001f; float h = 2f * d * Mathf.Tan(halfFov) * 1.1f; var quad = GameObject.CreatePrimitive(PrimitiveType.Quad); var col = quad.GetComponent\u003cCollider\u003e(); if (col != null) Destroy(col); quad.name = \\\"Overdraw_\\\"